INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Arbeitssicherheit nur für gefährliche Berufe relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Arbeitsplätze"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Arbeitssicherheit?', 3, '[{"text": "Unfälle verhindern", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Produktivität steigern", "correct": false, "because": "Indirekter Effekt"}, {"text": "Kosten senken", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Arbeitssicherheit?', 5, '[{"text": "Gefährdungsbeurteilung", "correct": true, "because": "Identifiziert Risiken"}, {"text": "Schutzausrüstung", "correct": true, "because": "Minimiert Gefahren"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitssicherheit ist gesetzlich vorgeschrieben. b) Sie gilt nur für große Firmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Firmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeitssicherheit?', 4, '[{"text": "Arbeitsbedingungen", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Schulungen", "correct": false, "because": "Prävention wichtig"}, {"text": "Bürodekor", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Arbeitssicherheit Schulungen umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Sensibilisiert Mitarbeiter"}, {"text": "Nein", "correct": false, "because": "Teil der Maßnahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Arbeitssicherheit?', 3, '[{"text": "Arbeitsschutzgesetz", "correct": true, "because": "Grundlage in Deutschland"}, {"text": "Steuergesetz", "correct": false, "because": "Anderer Bereich"}, {"text": "Verkehrsrecht", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Umsetzung von Arbeitssicherheit?', 5, '[{"text": "Risikoanalysen", "correct": true, "because": "Identifiziert Gefahren"}, {"text": "Sicherheitsvorschriften", "correct": true, "because": "Regelt Verhalten"}, {"text": "Produktwerbung", "correct": false, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Arbeitssicherheit schützt vor Unfällen. b) Sie ist optional. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gesetzlich verpflichtend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Arbeitssicherheit unwichtig?', 4, '[{"text": "Schutzkleidung", "correct": false, "because": "Schützt Mitarbeiter"}, {"text": "Sicherheitsunterweisung", "correct": false, "because": "Pflicht"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt Arbeitssicherheit auch im Homeoffice?', 2, '[{"text": "Ja", "correct": true, "because": "Arbeitgeber verantwortlich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt Arbeitssicherheit?', 4, '[{"text": "Weniger Unfälle", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Rechtliche Absicherung", "correct": true, "because": "Erfüllt Vorschriften"}, {"text": "Höhere Gewinne", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Arbeitssicherheit nur für Arbeitnehmer ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schützt auch Arbeitgeber"}, {"text": "Ja", "correct": false, "because": "Beidseitiger Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Arbeitssicherheit?', 3, '[{"text": "Gefahrenprävention", "correct": true, "because": "Kernaufgabe"}, {"text": "Kostenreduktion", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitssicherheit umfasst Brandschutz. b) Sie ist nur für Büros relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Bereiche"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat mangelnde Arbeitssicherheit?', 5, '[{"text": "Höhere Unfallquote", "correct": true, "because": "Risiken steigen"}, {"text": "Rechtliche Konsequenzen", "correct": true, "because": "Verstöße strafbar"}, {"text": "Schnellere Arbeit", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Arbeitssicherheit unwichtig?', 3, '[{"text": "Risikobeurteilung", "correct": false, "because": "Grundlage"}, {"text": "Sicherheitsausrüstung", "correct": false, "because": "Schutzmaßnahme"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Umfasst Arbeitssicherheit auch psychische Gesundheit?', 3, '[{"text": "Ja", "correct": true, "because": "Stressprävention enthalten"}, {"text": "Nein", "correct": false, "because": "Ganzheitlicher Ansatz"}]'),
